import{c as e,S as l,j as a,m as r}from"./chunks/framework.8aa1YH_s.js";const g=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 17: Kelime Türleri - Fiiller ve Fiil Çatıları","description":"","frontmatter":{},"headers":[],"relativePath":"17 Kelime Türleri - Fiiller ve Fiil Çatıları.md","filePath":"17 Kelime Türleri - Fiiller ve Fiil Çatıları.md"}'),n={name:"17 Kelime Türleri - Fiiller ve Fiil Çatıları.md"};function t(d,i,s,o,m,u){return l(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="turk-dil-bilgisi-serisi-17-kelime-turleri-fiiller-ve-fiil-catıları" tabindex="-1">Türk Dil Bilgisi Serisi - 17: Kelime Türleri - Fiiller ve Fiil Çatıları <a class="header-anchor" href="#turk-dil-bilgisi-serisi-17-kelime-turleri-fiiller-ve-fiil-catıları" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 17: Kelime Türleri - Fiiller ve Fiil Çatıları”">​</a></h1><p>Kelime türleri yolculuğumuzun bu büyük finalinde, dilimizin motoru ve kalbi sayılan <strong>Fiiller (Eylemler)</strong> konusuna derinlemesine bir dalış yapıyoruz. Prof. Dr. Muharrem Ergin’e göre fiiller; iş, oluş, kılış ve hareket bildiren, zaman ve şahsa bağlanarak dildeki dinamizmi sağlayan en güçlü kelime sınıfıdır.</p><p>Bu yazımızda fiillerin genel yapısını ve özellikle cümle yapısını doğrudan etkileyen <strong>Fiil Çatıları (Özne-Nesne İlişkileri)</strong> konusunu ele alacağız.</p><hr><h2 id="_1-fiil-eylem-nedir" tabindex="-1">1. Fiil (Eylem) Nedir? <a class="header-anchor" href="#_1-fiil-eylem-nedir" aria-label="Permalink to “1. Fiil (Eylem) Nedir?”">​</a></h2><p>Kainattaki her türlü eylemi, durum değişikliğini, oluşu ve kılışı zamana, kiplemeye ve şahsa bağlı olarak karşılayan kelimelere <strong>fiil</strong> denir. Fiiller, isim soylu kelimeler gibi durağan değildir; bünyelerinde mutlaka bir &quot;akış&quot; ve &quot;hareket&quot; barındırırlar. Ayırt edici özellikleri, daha önce de gördüğümüz gibi <code>-mak / -mek</code> mastar ekini alabilmeleridir.</p><hr><h2 id="_2-fiil-catıları-eylemin-iliskiler-agı" tabindex="-1">2. Fiil Çatıları (Eylemin İlişkiler Ağı) <a class="header-anchor" href="#_2-fiil-catıları-eylemin-iliskiler-agı" aria-label="Permalink to “2. Fiil Çatıları (Eylemin İlişkiler Ağı)”">​</a></h2><p>Fiil çatısı, bir fiilin cümledeki <strong>özne</strong> (işi yapan) ve <strong>nesne</strong> (işten etkilenen) ile kurduğu dil bilgisel ilişkinin adıdır. Muharrem Ergin sistematiğinde çatılar iki ana grupta incelenir:</p><p>[ FİİL ÇATILARI ] | +-----------------+-----------------+ | | [ ÖZNESİNE GÖRE ÇATILAR ] [ NESNESİNE GÖRE ÇATILAR ]</p><hr><h2 id="i-oznelerine-gore-fiil-catıları" tabindex="-1">I. Öznelerine Göre Fiil Çatıları <a class="header-anchor" href="#i-oznelerine-gore-fiil-catıları" aria-label="Permalink to “I. Öznelerine Göre Fiil Çatıları”">​</a></h2><p>Eylemin, özne (işi yapan unsur) tarafından nasıl gerçekleştirildiğini ve öznenin eylem karşısındaki durumunu belirten çatılardır.</p><h3 id="_1-etken-fiiller" tabindex="-1">1. Etken Fiiller <a class="header-anchor" href="#_1-etken-fiiller" aria-label="Permalink to “1. Etken Fiiller”">​</a></h3><p>İşi yapan gerçek veya gizli bir öznenin cümlede açıkça belli olduğu fiillerdir. Eylem doğrudan özne tarafından icra edilir. Herhangi bir çatı eki almazlar (Yalındırlar).</p><ul><li><em>Örnek:</em> Ahmet projeyi başarıyla <strong>tamamladı</strong>. (<em>Tamamlayan kim? -&gt; Ahmet: Gerçek Özne.</em>)</li></ul><h3 id="_2-edilgen-fiiller-ıl-il-ul-ul-veya-ın-in-un-un" tabindex="-1">2. Edilgen Fiiller (<code>-ıl / -il / -ul / -ül</code> veya <code>-ın / -in / -un / -ün</code>) <a class="header-anchor" href="#_2-edilgen-fiiller-ıl-il-ul-ul-veya-ın-in-un-un" aria-label="Permalink to “2. Edilgen Fiiller (-ıl / -il / -ul / -ül veya -ın / -in / -un / -ün)”">​</a></h3><p>İşi yapanın tam olarak bilinmediği, eylemden etkilenen nesnenin zorunlu olarak &quot;Özne&quot; (Sözde Özne) konumuna yükseldiği çatılardır.</p><ul><li><em>Örnek:</em> Proje başarıyla <strong>tamamlandı</strong>. (<em>Tamamlayan kim? -&gt; Belli değil. Tamamlanan ne? -&gt; Proje: Sözde Özne.</em>)</li></ul><h3 id="_3-donuslu-fiiller-ın-in-un-un-veya-ıl-il" tabindex="-1">3. Dönüşlü Fiiller (<code>-ın / -in / -un / -ün</code> veya <code>-ıl / -il</code>) <a class="header-anchor" href="#_3-donuslu-fiiller-ın-in-un-un-veya-ıl-il" aria-label="Permalink to “3. Dönüşlü Fiiller (-ın / -in / -un / -ün veya -ıl / -il)”">​</a></h3><p>Eylemi yapan da, o eylemden etkilenen de <strong>aynı öznedir</strong>. İş öne dönüp dolaşıp yine özneye gelir.</p><ul><li><em>Örnek:</em> Mehmet sınavı kazanınca çok <strong>sevindi</strong>. (<em>Sevinen kim? -&gt; Mehmet. Sevinme işinden etkilenen kim? -&gt; Yine Mehmet.</em>)</li></ul><h3 id="_4-istes-fiiller-ıs-is-us-us" tabindex="-1">4. İşteş Fiiller (<code>-ış / -iş / -uş / -üş</code>) <a class="header-anchor" href="#_4-istes-fiiller-ıs-is-us-us" aria-label="Permalink to “4. İşteş Fiiller (-ış / -iş / -uş / -üş)”">​</a></h3><p>Eylemin birden fazla özne tarafından <strong>karşılıklı</strong> ya da <strong>birlikte (ortaklaşa)</strong> yapıldığını bildiren çatılardır.</p><ul><li><em>Karşılıklı Örnek:</em> İki boksör saatlerce <strong>dövüştü</strong>. / Eski dostuyla <strong>selamlaştı</strong>.</li><li><em>Birlikte Örnek:</em> Kuşlar havada <strong>uçuşuyor</strong>. / Çocuklar ansızın <strong>kaçıştı</strong>.</li></ul><hr><h2 id="ii-nesnelerine-gore-fiil-catıları" tabindex="-1">II. Nesnelerine Göre Fiil Çatıları <a class="header-anchor" href="#ii-nesnelerine-gore-fiil-catıları" aria-label="Permalink to “II. Nesnelerine Göre Fiil Çatıları”">​</a></h2><p>Fiillerin nesne (işten etkilenen varlık) alıp alamama durumlarına ve aldıkları eklere göre şekillenen çatılardır.</p><h3 id="_1-gecisli-fiiller" tabindex="-1">1. Geçişli Fiiller <a class="header-anchor" href="#_1-gecisli-fiiller" aria-label="Permalink to “1. Geçişli Fiiller”">​</a></h3><p>Nesne alabilen, yani yapılan işten etkilenecek somut bir varlığa ihtiyaç duyan fiillerdir. Fiilin başına <strong>&quot;Onu&quot;</strong> kelimesini getirdiğimizde anlamlı bir bütün oluşur. Cümlede &quot;Neyi?, Kimi?, Ne?&quot; sorularına cevap verirler.</p><ul><li><em>Örnek:</em> Kitabı kütüphaneden <strong>aldım</strong>. (<em>Onu aldım -&gt; Anlamlı. Neyi aldım? -&gt; Kitabı: Nesne.</em>)</li></ul><h3 id="_2-gecissiz-fiiller" tabindex="-1">2. Geçişsiz Fiiller <a class="header-anchor" href="#_2-gecissiz-fiiller" aria-label="Permalink to “2. Geçişsiz Fiiller”">​</a></h3><p>Nesne alamayan, bünyesi gereği bir nesneye ihtiyaç duymayan fiillerdir. Genellikle bir durumu veya oluşu bildirirler. Fiilin başına <strong>&quot;Onu&quot;</strong> kelimesi getirildiğinde tamamen anlamsız olur.</p><ul><li><em>Örnek:</em> Bebek beşikte rahatça <strong>uyudu</strong>. (<em>Onu uyudu -&gt; Anlam dışı, geçişsizdir.</em>)</li></ul><h3 id="_3-ettirgen-fiiller-r-t-tır-tir" tabindex="-1">3. Ettirgen Fiiller (<code>-r, -t, -tır / -tir</code>) <a class="header-anchor" href="#_3-ettirgen-fiiller-r-t-tır-tir" aria-label="Permalink to “3. Ettirgen Fiiller (-r, -t, -tır / -tir)”">​</a></h3><p>Zaten <strong>geçişli olan</strong> bir fiilin üzerine bu ekler getirilerek, onun geçişlilik derecesinin daha da artırılmasıdır. İşi &quot;başkasına yaptırma&quot; anlamı baskındır.</p><ul><li><em>Formül:</em> <code>Geçişli Fiil + Çatı Eki = Ettirgen Fiil</code></li><li><em>Örnek:</em> Okudu (<em>Geçişli</em>) $$\\rightarrow$$ Oku-<strong>t</strong>-tu (<em>Ettirgen - Başkasına okuttu</em>).</li></ul><h3 id="_4-oldurgan-fiiller-r-t-tır-tir" tabindex="-1">4. Oldurgan Fiiller (<code>-r, -t, -tır / -tir</code>) <a class="header-anchor" href="#_4-oldurgan-fiiller-r-t-tır-tir" aria-label="Permalink to “4. Oldurgan Fiiller (-r, -t, -tır / -tir)”">​</a></h3><p>Aslında <strong>geçişsiz olan</strong> (nesne alamayan) bir fiilin üzerine bu ekler getirilerek, o fiilin zorla <strong>geçişli hale getirilmesi (oldurulması)</strong> hadisesidir.</p><ul><li><em>Formül:</em> <code>Geçişsiz Fiil + Çatı Eki = Oldurgan Fiil</code></li><li><em>Örnek:</em> Ağladı (<em>Geçişsiz - Onu ağladı olmaz</em>) $$\\rightarrow$$ Ağla-<strong>t</strong>-tı (<em>Oldurgan - Onu ağlattı artık olur</em>).</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin&#39;in sistematiğinde fiiller ve onların çatı özellikleri, Türkçenin cümle kurgusundaki o meşhur esnekliğini ve anlam zenginliğini doğurur. Tek bir çatı ekiyle (<code>-ış, -ıl, -t</code>) eylemin yönünü, işin kime ait olduğunu ve kuralın nasıl işlediğini tek hamlede değiştirebiliriz. Fiiller, Türk dil bilgisinin şekil ve anlam yönünden en zirve noktasıdır.</p>',43)])])}const h=e(n,[["render",t]]);export{g as __pageData,h as default};
